import{c as t,Q as n,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"End-of-event checklist","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/end-of-event-checklist.md","filePath":"user/after-the-event/end-of-event-checklist.md"}'),r={name:"user/after-the-event/end-of-event-checklist.md"};function s(i,e,l,h,d,c){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="end-of-event-checklist" tabindex="-1">End-of-event checklist <a class="header-anchor" href="#end-of-event-checklist" aria-label="Permalink to &quot;End-of-event checklist&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers wrapping up after the competition.</p><p>A single-page checklist of everything to do once the last competitor has finished — or been accounted for. Each item links to the relevant detailed page.</p><blockquote><p><strong>Status:</strong> Stub — not yet written.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><h3 id="before-leaving-the-venue" tabindex="-1">Before leaving the venue <a class="header-anchor" href="#before-leaving-the-venue" aria-label="Permalink to &quot;Before leaving the venue&quot;">​</a></h3><ul><li>[ ] Confirm all competitors are accounted for — the <strong>On Course</strong> count should be zero (see <a href="./../running-the-event/safety-check">Safety check: accounting for everyone</a>)</li><li>[ ] Resolve any outstanding status issues (disputed results, missing punches)</li><li>[ ] Give everyone a result: mark the non-starters <strong>DNS</strong> (<strong>Competitors → Actions → Set competitors DNS…</strong>), and download every card or set the runner <strong>DNF</strong> or <strong>Overtime</strong>. <strong>Finish event</strong>, and publishing a results file (<strong>Publish → Export IOF XML</strong>, <strong>Export JSON</strong> or <strong>Upload to Eventor</strong>), both stop at <strong>Event not finalised</strong> while anyone has no status, is still on course, or has only a radio finish, or a card the radio saw finish is neither downloaded nor entered, with buttons to set them DNS, overtime or (for a radio finish) DNF, and to open the <strong>Pending</strong> list. <strong>Finish event</strong> won&#39;t go past a pending runner at all: a radio finish with no download, or a card nobody is entered on — see <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a></li><li>[ ] Collect and check in all hire cards</li><li>[ ] Publish the results</li><li>[ ] Upload results to Eventor directly from the <strong>Results</strong> view (<strong>Publish → Upload to Eventor</strong>), and export any files other systems need (IOF XML, PDF)</li><li>[ ] Take a backup of the event data</li></ul><blockquote><p><strong>Note:</strong> Finishing the event isn&#39;t final. If a competitor turns up afterwards — even the next day — open the event and click <strong>Restart event</strong> to take it live again, download their card, and finish it a second time. See <a href="./../running-the-event/dashboard#restarting-an-event-youve-already-finished">Restarting an event you&#39;ve already finished</a>.</p></blockquote><h3 id="back-at-home" tabindex="-1">Back at home <a class="header-anchor" href="#back-at-home" aria-label="Permalink to &quot;Back at home&quot;">​</a></h3><ul><li>[ ] Upload results to Eventor / federation portal if you couldn&#39;t do it on-site</li><li>[ ] Archive the event in Manager</li><li>[ ] Review the event for lessons learned (any recurring issues to add to troubleshooting?)</li><li>[ ] Disconnect or power down the server (if it&#39;s not a permanent installation)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./results">Results</a></li><li><a href="./exports">Exporting data</a></li><li><a href="./../reference/backup-and-restore">Backup and restore</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li></ul>',12)])])}const f=t(r,[["render",s]]);export{g as __pageData,f as default};
